CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'buyer' CHECK(role IN ('buyer','seller')));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS homes(id SERIAL PRIMARY KEY,owner_id INTEGER REFERENCES users(id),title TEXT NOT NULL,city TEXT NOT NULL,neighborhood TEXT NOT NULL,price INTEGER NOT NULL,kind TEXT NOT NULL,type TEXT NOT NULL,beds INTEGER NOT NULL,baths INTEGER NOT NULL,area INTEGER NOT NULL,photo TEXT NOT NULL,description TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 0,latitude REAL,longitude REAL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,owner_id INTEGER REFERENCES users(id),photo_data BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users(id),home_id INTEGER REFERENCES homes(id) ON DELETE CASCADE,PRIMARY KEY(user_id,home_id));
CREATE TABLE IF NOT EXISTS inquiries(id SERIAL PRIMARY KEY,home_id INTEGER REFERENCES homes(id) ON DELETE CASCADE,sender_id INTEGER REFERENCES users(id),message TEXT NOT NULL,viewing_at TEXT,viewing_status TEXT NOT NULL DEFAULT 'requested',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS replies(id SERIAL PRIMARY KEY,inquiry_id INTEGER REFERENCES inquiries(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS user_signals(user_id INTEGER PRIMARY KEY,version BIGINT NOT NULL);
